function deductionRow(name='',cents=''){return `<div class="deduction-row"><input name="deductionName" placeholder="Tax, insurance, or other deduction" maxlength="80" value="${esc(name)}" aria-label="Deduction name"><input name="deductionAmount" type="number" min="0" max="1000000" step="0.01" value="${cents===''?'':(cents/100).toFixed(2)}" placeholder="0.00" aria-label="Deduction amount"><button type="button" class="mini-action danger" data-action="remove-deduction" aria-label="Remove deduction">✕</button></div>`;}
const paycheckDrafts=new Map();
function paycheckPeriods(){if(!state.records.some(r=>r.id===active.id))paycheckDrafts.set(active.id,active);for(const r of state.records)paycheckDrafts.delete(r.id);const records=new Map(paycheckDrafts);for(const r of state.records)records.set(r.id,r);return [...records.values()].sort((a,b)=>b.start.localeCompare(a.start)||a.cycle.localeCompare(b.cycle));}
function paycheckPeriodLabel(record){const range=cycleRange(record.start,record.cycle,record.end);return date(range.start)+', '+range.start.slice(0,4)+' – '+date(range.end)+', '+range.end.slice(0,4)+' · '+cycleName(range.cycle);}
function paycheckPeriodHint(){return state.records.some(r=>r.id===active.id)?'Linked to '+paycheckPeriodLabel(active)+'.':'This period will be saved with your paycheck. You can add timesheet hours later.';}
function refreshPaycheckPeriod(){const select=$('recordId');select.innerHTML='<option value="" disabled>Choose a period</option>'+options(paycheckPeriods().map(r=>[r.id,paycheckPeriodLabel(r)]),active.id);$('paycheck-period-summary').textContent=paycheckPeriodHint();}
function updatePaycheckCalendar(){const start=$('paycheck-period-start'),end=$('paycheck-period-end'),cycle=$('paycheck-period-cycle').value,custom=cycle==='custom',preview=$('paycheck-range-preview'),use=$('use-paycheck-period');end.readOnly=!custom;end.min=custom?(start.value||'1900-01-01'):'1900-01-01';try{const range=cycleRange(start.value,cycle,end.value);if(!custom)end.value=range.end;preview.textContent=date(range.start)+', '+range.start.slice(0,4)+' – '+date(range.end)+', '+range.end.slice(0,4)+' · '+range.days+' '+(range.days===1?'day':'days')+' · Both dates included';preview.classList.remove('red');end.removeAttribute('aria-invalid');use.disabled=false;}catch(error){preview.textContent=error.message;preview.classList.add('red');end.setAttribute('aria-invalid','true');use.disabled=true;}}
function usePaycheckPeriod(){const range=cycleRange($('paycheck-period-start').value,$('paycheck-period-cycle').value,$('paycheck-period-end').value),record=paycheckPeriods().find(r=>r.id===rangeId(range))??newRecord(range.start,range.cycle,state.settings.rate||active.rate,active.mode,range.end);selectRecord(record);refreshPaycheckPeriod();$('paycheck-period-creator').open=false;$('recordId').focus();}
function paychecksView(){return head('Make sure payday adds up.','Compare gross pay with your hours. Track deductions separately.',budgetButton()+balanceButton()+spendingButton())+`<div class="two-column"><section class="panel"><div class="section-head"><h2>Record a paycheck</h2></div>
 <div class="paycheck-period-controls"><label for="recordId">Pay-cycle timesheet</label><select name="recordId" id="recordId" form="paycheck-form" required aria-describedby="paycheck-period-summary"><option value="" disabled>Choose a period</option>${options(paycheckPeriods().map(r=>[r.id,paycheckPeriodLabel(r)]),active.id)}</select><p class="field-hint" id="paycheck-period-summary" aria-live="polite">${esc(paycheckPeriodHint())}</p>
 <details id="paycheck-period-creator" class="paycheck-period-creator"><summary>Choose dates on calendar</summary><div class="form-grid"><div><label for="paycheck-period-start">Period start date</label><input id="paycheck-period-start" type="date" value="${active.start}" min="1900-01-01" max="9998-12-31"></div><div><label for="paycheck-period-end">Period end date</label><input id="paycheck-period-end" type="date" value="${cycleRange(active.start,active.cycle,active.end).end}" min="${active.start}" max="9998-12-31"></div><div class="full"><label for="paycheck-period-cycle">Period cycle</label><select id="paycheck-period-cycle">${options(['custom','7','14','15','semimonth','month'].map(c=>[c,cycleName(c)]),'custom')}</select></div><p id="paycheck-range-preview" class="field-hint full" aria-live="polite">Both dates are included. Choose a custom range of up to 366 days, or use a cycle preset.</p><div class="full">${button('use-paycheck-period','Use this period','','id="use-paycheck-period"')}</div></div></details></div>
 <form id="paycheck-form" class="form-grid">
 ${field('Payday','payDate',today(),'date','required')}${field('Gross amount on paycheck ($)','gross','','number','required min="0" max="1000000" step="0.01"')}<div class="full"><label>Deductions</label><div id="deductions">${deductionRow('Taxes')}${deductionRow('Other deductions')}</div><button type="button" class="mini-action" data-action="add-deduction">Add deduction</button><p class="field-hint">Use the actual figures on your pay stub. Tax estimates are not deducted automatically.</p></div><div class="full"><button class="button">Save & compare paycheck</button></div></form></section>
 <section class="panel"><div class="section-head"><h2>Your paycheck checks</h2><span class="tag">${state.paychecks.length}</span></div>${state.paychecks.slice().sort((a,b)=>b.payDate.localeCompare(a.payDate)).map(p=>{const r=state.records.find(r=>r.id===p.recordId),c=paycheckSummary(p,r,state.records,state.settings),t=r?calculate(r,state.records,state.settings):null,canCompare=t?.completed>0&&!t.errors.length;return `<article style="margin-bottom:23px"><div class="list-item"><div><strong>Paid ${date(p.payDate)}, ${p.payDate.slice(0,4)}</strong><p>${r?esc(paycheckPeriodLabel(r)):'Timesheet removed'}</p></div><div class="button-row">${r?button('open-record','Edit timesheet','secondary','data-id="'+esc(r.id)+'"'):''}${button('spending-chart','View spending','secondary','data-id="'+esc(p.id)+'" aria-haspopup="dialog" aria-controls="spending-dialog"')}<button class="mini-action danger" data-action="delete-paycheck" data-id="${p.id}">Delete</button></div></div><div class="list-item"><span>Expected / actual gross</span><strong>${canCompare?money(c.expected/100):'—'} / ${money(c.actual/100)}</strong></div><div class="list-item"><span>Gross difference</span><strong class="${canCompare?(c.difference<0?'red':'green'):''}">${canCompare?money(c.difference/100):'—'}</strong></div><div class="list-item"><span>Deductions / take-home</span><strong>${money(c.deductions/100)} / ${money(c.net/100)}</strong></div>${r&&!canCompare?`<p class="notice warning">${t.errors.length?'Fix incomplete timesheet entries before relying on this comparison.':'Add hours in this period’s timesheet to compare expected pay.'}</p>`:''}</article>`;}).join('')||empty('No paychecks recorded','Add the gross amount and deductions from your first pay stub.')}</section></div>`;}
function expensesView(){const r=cycleRange(active.start,active.cycle,active.end),b=budgetSummary(state,r.start,r.end);return head('Keep spending in step with pay.',`${date(r.start)} – ${date(r.end)} · Your current pay cycle`,button('expense-csv','Download expenses CSV','export')+budgetButton()+balanceButton()+spendingButton())+`<section class="stats">${stat('Take-home received',money(b.received/100),'Uses actual recorded paychecks',true)}${stat('Spent this cycle',money(b.expenses/100),'Your recorded expenses')}${stat('Bills reserved',money(b.reserved/100),'Upcoming unpaid bills')}${stat('Available to spend',money(b.available/100),'Income − expenses − unpaid bills')}</section><div class="two-column"><div class="stack"><section class="panel"><div class="section-head"><h2>Add an expense</h2></div><form id="expense-form" class="form-grid">${field('Date','expenseDate',today(),'date','required')}${field('Amount ($)','amount','','number','required min="0.01" max="1000000" step="0.01"')}<div><label for="category">Category</label><select name="category" id="category">${options(expenseCategories(state).map(c=>[c,c]),'Food')}</select></div>${field('Note','note','','text','maxlength="500" placeholder="Groceries, fuel, or a purchase"')}<div class="full"><button class="button">Save expense</button></div></form></section><section class="panel"><div class="section-head"><h2>Expense history</h2><input class="search" id="expense-search" type="search" placeholder="Search expenses" aria-label="Search expenses"></div><div id="expense-list">${expenseRows('')}</div></section></div><div class="stack"><section class="panel"><div class="section-head"><h2>Recurring bills</h2></div><form id="bill-form" class="form-grid">${field('Bill name','billName','','text','required maxlength="120" placeholder="Rent, phone, insurance…"')}${field('Amount ($)','billAmount','','number','required min="0.01" max="1000000" step="0.01"')}${field('First due date','nextDue',today(),'date','required')}<div><label for="frequency">Repeats</label><select name="frequency" id="frequency">${options([['monthly','Monthly'],['weekly','Weekly'],['once','Once']],'monthly')}</select></div><div class="full"><button class="button secondary">Add bill</button></div></form><div style="margin-top:18px">${state.bills.map(b=>`<div class="list-item"><div><strong>${esc(b.name)}</strong><p>${money(b.cents/100)} · ${b.frequency} · from ${date(b.nextDue)}</p></div><button class="mini-action danger" data-action="delete-bill" data-id="${b.id}">Remove</button></div>`).join('')}</div>${billOccurrences(state.bills,r.start,r.end).filter(b=>!state.expenses.some(e=>e.billId===b.id&&e.billDate===b.occurrence)).map(b=>`<div class="list-item"><div><strong>${esc(b.name)} due ${date(b.occurrence)}</strong><p>${money(b.cents/100)}</p></div><button class="mini-action" data-action="pay-bill" data-id="${b.id}" data-date="${b.occurrence}">Mark paid</button></div>`).join('')}</section><section class="panel" id="budget-overview">${budgetOverview()}</section></div></div>`;}
function expenseRows(query){return state.expenses.filter(e=>(e.note+' '+e.category+' '+e.date).toLowerCase().includes(query.toLowerCase())).sort((a,b)=>b.date.localeCompare(a.date)).slice(0,150).map(e=>`<div class="list-item"><div><strong>${esc(e.note||e.category)}</strong><p>${date(e.date)}, ${e.date.slice(0,4)} · ${esc(e.category)}</p></div><div><span class="amount">${money(e.cents/100)}</span><button class="mini-action danger" data-action="delete-expense" data-id="${e.id}" style="margin-left:8px">Delete</button></div></div>`).join('')||empty('No matching expenses','Add a purchase above to start tracking spending.');}
function renderExpenseList(query){$('expense-list').innerHTML=expenseRows(query);}
function supportView(){return head('Help & account controls','Your data, backups, and a way to get help.')+`<div class="two-column"><div class="stack"><section class="panel"><div class="section-head"><h2>Your private account</h2></div><p><strong>${esc(user.name)}</strong><br><span class="muted">${esc(user.email)} · signed in with ${esc(user.provider)}</span></p><p class="muted small" style="margin-top:16px">Only your signed-in account can read or change these cloud records. EasyTime uses hosted authentication and does not store your password.</p><div class="button-row" style="margin-top:20px">${button('backup','Download readable backup','export')}${button('signout','Sign out')}</div></section><section class="panel"><h2>Import & restore</h2><p class="muted small" style="margin:12px 0 20px">Your readable backup opens as a page with clear tables. Choose Restore a backup to bring records back from that page or an earlier JSON backup. You can print the readable page or save it as a PDF using your browser’s Print menu.</p><div class="button-row">${button('import-local','Import local timesheets')}<label class="button secondary" for="backup-file" style="margin:0;cursor:pointer">Restore a backup</label><input id="backup-file" type="file" accept="text/html,application/json,.html,.htm,.json" hidden>${button('load-backups','Show recent cloud backups')}</div><p class="field-hint">Choose the original downloaded HTML or JSON file when restoring. A printed PDF is for reading.</p><details style="margin-top:18px"><summary>More backup options</summary><p class="field-hint">If another tool needs a data file, you can also download the earlier JSON format.</p>${button('backup-json','Download data file (JSON)','secondary')}</details><div id="backup-list" style="margin-top:18px"></div></section><section class="panel"><h2>Delete account data</h2><p class="muted small" style="margin:12px 0 18px">Deletes your EasyTime records, expenses, profile, and cloud backups. Export your data first. Your ChatGPT or Google identity is separate.</p>${button('delete-account','Delete my EasyTime data','danger')}</section></div><div class="stack"><section class="panel"><h2>Ask for help</h2><form id="support-form" class="form-grid" style="margin-top:20px">${field('Subject','subject','','text','required maxlength="150"')}<div class="full"><label for="message">What happened?</label><textarea name="message" id="message" required maxlength="5000" placeholder="Describe the issue and what you expected."></textarea></div><div class="full"><button class="button">Save support request</button></div></form><p class="field-hint">Your request is stored privately for review by the EasyTime operator. No email is sent automatically.</p><div id="support-list"></div></section><section class="panel"><h2>Privacy & records</h2><p class="muted" style="margin-top:12px;font-size:.875rem">Profile details, work times, expenses, and paycheck figures are stored in your private cloud account. Each API request checks ownership. Export and delete your data here. Recent cloud versions are kept for recovery, and they are deleted with your account.</p><p class="muted small" style="margin-top:16px">Bank connections, automatic tax calculations, and automatic payroll submission are not enabled.</p></section></div></div>`;}
async function loadSupport(){try{const result=await api('support');if($('support-list'))$('support-list').innerHTML=result.tickets.map(t=>`<div class="list-item"><div><strong>${esc(t.subject)}</strong><p>${esc(t.message)}</p><small>${new Date(t.created_at).toLocaleDateString()} · ${esc(t.status)}</small></div></div>`).join('');}catch(e){toast(e.message);}}
function reminders(){if(!state.settings.reminders)return [];const now=today(),end=addDays(now,7),rows=[];for(const b of billOccurrences(state.bills,now,end)){if(state.expenses.some(e=>e.billId===b.id&&e.billDate===b.occurrence))continue;rows.push({id:'bill:'+b.id+':'+b.occurrence,date:b.occurrence,title:b.name,copy:money(b.cents/100)+' due',bill:b});}for(const r of state.records){const t=calculate(r,state.records,state.settings),payday=addDays(t.range.end,state.settings.paydayOffset);if(payday>=now&&payday<=end&&!state.paychecks.some(p=>p.recordId===r.id))rows.push({id:'pay:'+r.id,date:payday,title:'Expected payday',copy:money(t.pay)+' estimated gross · '+date(r.start)});}const range=cycleRange(active.start,active.cycle,active.end),i=Math.round((Date.parse(now+'T12:00:00Z')-Date.parse(range.start+'T12:00:00Z'))/86400000);if(i>=0&&i<range.days&&!active.entries[i].start)rows.push({id:'shift:'+now,date:now,title:'Add today’s shift',copy:'Keep your next paycheck estimate up to date.'});return rows.filter(r=>!state.dismissed.includes(r.id)).sort((a,b)=>a.date.localeCompare(b.date));}
function reminderHTML(){return reminders().map(r=>`<div class="list-item"><div><strong>${esc(r.title)}</strong><p>${date(r.date)} · ${esc(r.copy)}</p></div><button class="mini-action" data-action="dismiss" data-id="${esc(r.id)}" aria-label="Dismiss ${esc(r.title)} reminder">Dismiss</button></div>`).join('')||empty('You’re up to date','No reminders due in the next seven days.');}
function refreshReminders(){if(!user||!active)return;$('reminder-count').textContent=reminders().length;if($('reminder-dialog').open)$('reminder-list').innerHTML=reminderHTML();}
function calendar(){const clean=s=>String(s).replaceAll('\\','\\\\').replaceAll('\n','\\n').replaceAll('\r','').replaceAll(',','\\,').replaceAll(';','\\;'),rows=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//EasyTime//Payday reminders//EN','CALSCALE:GREGORIAN'];for(const r of reminders()){rows.push('BEGIN:VEVENT','UID:'+clean(r.id)+'@easytime','DTSTAMP:'+new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,''),'DTSTART;VALUE=DATE:'+r.date.replaceAll('-',''),'DTEND;VALUE=DATE:'+addDays(r.date,1).replaceAll('-',''),'SUMMARY:'+clean(r.title),'DESCRIPTION:'+clean(r.copy),'BEGIN:VALARM','ACTION:DISPLAY','TRIGGER:-PT9H','DESCRIPTION:'+clean(r.title),'END:VALARM','END:VEVENT');}rows.push('END:VCALENDAR');download(rows.join('\r\n')+'\r\n','EasyTime-reminders.ics','text/calendar;charset=utf-8');}
const formData=form=>Object.fromEntries(new FormData(form)),cents=v=>{const n=Number(v);if(!Number.isFinite(n)||n<0||n>1000000)throw new Error('Enter a valid amount.');return Math.round(n*100);};
$('view').addEventListener('submit',async e=>{e.preventDefault();const form=e.target,v=formData(form);try{const next=structuredClone(state);switch(form.id){
 case 'profile-form':next.profile={...next.profile,fullName:v.fullName.trim(),employeeId:v.employeeId.trim(),company:v.company.trim(),email:v.email.trim(),rate:v.rate};if(v.rate!=='')next.settings.rate=v.rate;break;
 case 'settings-form':next.settings={...next.settings,...v,weekStart:Number(v.weekStart),otThreshold:Number(v.otThreshold),otMultiplier:Number(v.otMultiplier),paydayOffset:Number(v.paydayOffset),reminders:form.elements.reminders.checked};break;
 case 'rate-form':if(next.settings.rateHistory.some(r=>r.effective===v.effective))throw new Error('A rate already starts on that date. Remove it before adding another.');next.settings.rateHistory.push({effective:v.effective,rate:v.historyRate});break;
 case 'expense-form':next.expenses.push({id:id(),date:v.expenseDate,cents:cents(v.amount),category:v.category,note:v.note.trim()});break;
 case 'bill-form':next.bills.push({id:id(),name:v.billName.trim(),cents:cents(v.billAmount),nextDue:v.nextDue,frequency:v.frequency,active:true});break;
 case 'paycheck-form':{const record=paycheckPeriods().find(r=>r.id===v.recordId);if(!record)throw new Error('Choose a valid pay period.');if(!next.records.some(r=>r.id===record.id))next.records.push(structuredClone(record));const deductions=[...form.querySelectorAll('.deduction-row')].map(row=>({name:row.querySelector('[name=deductionName]').value.trim()||'Other deduction',cents:cents(row.querySelector('[name=deductionAmount]').value||0)})).filter(d=>d.cents>0);next.paychecks.push({id:id(),recordId:v.recordId,payDate:v.payDate,grossCents:cents(v.gross),deductions});break;}
 case 'support-form':await api('support','POST',{subject:v.subject,message:v.message});form.reset();toast('Your support request is saved.');loadSupport();return;
 default:return;}
 validateState(next);state=next;active=state.records.find(r=>r.id===active.id)??active;touch();const saved=await flush();if(saved){toast('Saved to your private cloud account.');if(form.isConnected)route();}
 }catch(error){toast(error.message);}});
async function signout(){if(dirty&&!(await flush())){if(!confirm('Some changes are not saved. Download a backup before signing out?'))return;downloadAccountBackup();return;}await api('auth','POST',{action:'logout'});location.href='/signout-with-chatgpt?return_to=%2Feasytime%2Flogin.html';}
async function action(e){const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;try{
 if(a==='apply-sheet-period')changePeriod();
 else if(a==='use-paycheck-period')usePaycheckPeriod();
 else if(a==='budget')showBudget();
 else if(a==='available-balance')showBalance();
 else if(a==='spending-chart')showSpending(b.dataset.id);
 else if(a==='csv'){download(timesheetCSV(active,state),'EasyTime_'+active.start+'_'+(active.cycle==='custom'?'custom_'+active.end:active.cycle)+'.csv','text/csv;charset=utf-8');toast('CSV downloaded. Open it in Excel or Google Sheets.');}
 else if(a==='save-record')await saveActiveRecord();
 else if(a==='next-period'){if(dirty&&!(await flush()))return;const range=nextRange(cycleRange(active.start,active.cycle,active.end));selectRecord(state.records.find(r=>r.id===rangeId(range))??newRecord(range.start,range.cycle,state.settings.rate||active.rate,active.mode,range.end));route();}
 else if(a.startsWith('mode-')){active.mode=a==='mode-normal'?'normal':'overtime';try{localStorage.setItem('easytimeMode',active.mode);}catch{}putActive();$('mode-switch').classList.toggle('overtime',active.mode==='overtime');$('mode-switch').querySelectorAll('button').forEach(x=>x.setAttribute('aria-pressed',String(x.dataset.action===a)));document.querySelectorAll('.manual-cell').forEach(c=>c.hidden=active.mode==='normal');$('mode-description').textContent=active.mode==='normal'?'All worked hours use the regular rate.':'Overtime follows your fixed workweek.';$('mode-badge').textContent=active.mode==='normal'?'REGULAR PAY':'OVERTIME MODE';updateTotals();}
 else if(a==='open-record'){selectRecord(state.records.find(r=>r.id===b.dataset.id));location.hash='timesheet';route();}
 else if(a==='delete-record')showRecordDelete(b.dataset.id);
 else if(['delete-expense','delete-bill','delete-paycheck'].includes(a)){if(!confirm('Delete this item?'))return;const key={'delete-expense':'expenses','delete-bill':'bills','delete-paycheck':'paychecks'}[a];state[key]=state[key].filter(x=>x.id!==b.dataset.id);touch();if(await flush())route();}
 else if(a==='remove-rate'){if(!confirm('Remove this rate change? Earlier estimates may change.'))return;state.settings.rateHistory=state.settings.rateHistory.filter(r=>r.effective!==b.dataset.id);touch();if(await flush())route();}
 else if(a==='add-deduction'){if($('deductions').children.length>=30)throw new Error('Use at most 30 deductions.');$('deductions').insertAdjacentHTML('beforeend',deductionRow());}
 else if(a==='remove-deduction')b.closest('.deduction-row').remove();
 else if(a==='pay-bill'){const bill=state.bills.find(x=>x.id===b.dataset.id);if(state.expenses.some(x=>x.billId===bill.id&&x.billDate===b.dataset.date))return;state.expenses.push({id:id(),date:b.dataset.date,cents:bill.cents,category:'Utilities',note:bill.name,billId:bill.id,billDate:b.dataset.date});touch();if(await flush())route();}
 else if(a==='backup')downloadAccountBackup();
 else if(a==='backup-json')downloadAccountBackup(true);
 else if(a==='print')window.print();
 else if(a==='import-local'){const raw=localStorage.getItem('easytimeRecordsV1'),profile=localStorage.getItem('easytimeEmployeeProfileV1');if(!raw&&!profile)throw new Error('No earlier records were found on this browser. Use Restore a backup for records from another device.');const result=importLegacy(raw,profile,state);validateState(result.state);if(!confirm('Import '+result.imported+' records into this cloud account? Existing cloud records with the same period are kept.'))return;state=result.state;active=state.records.find(r=>r.id===active.id)??active;touch();if(await flush()){localImport=false;route();toast(result.imported+' records imported. Original browser records were kept.');}}
 else if(a==='expense-csv'){const rows=[['Date','Category','Note','Amount'],...state.expenses.map(e=>[e.date,e.category,e.note,(e.cents/100).toFixed(2)])];download('\uFEFF'+rows.map(r=>r.map(csvCell).join(',')).join('\r\n')+'\r\n','EasyTime-expenses.csv','text/csv;charset=utf-8');}
 else if(a==='dismiss'){state.dismissed.push(b.dataset.id);if(state.dismissed.length>500)state.dismissed=state.dismissed.slice(-500);touch();refreshReminders();if(currentView==='dashboard')route();}
 else if(a==='calendar')calendar();
 else if(a==='load-backups'){const result=await api('export?mode=backups');$('backup-list').innerHTML=result.backups.map(b=>`<div class="list-item"><div><strong>Version ${b.revision}</strong><p>${new Date(b.created_at).toLocaleString()}</p></div><button class="mini-action" data-action="restore-backup" data-id="${b.id}">Restore</button></div>`).join('')||empty('No backups yet','Your previous cloud version is kept when you save a change.');}
 else if(a==='restore-backup'){const result=await api('export?backup='+encodeURIComponent(b.dataset.id));validateState(result.state);if(!confirm('Restore this version? Your current cloud data will become a recovery backup.'))return;state=result.state;selectRecord(state.records.at(-1)??newRecord(today(),state.settings.cycle,state.settings.rate));touch();if(await flush()){route();toast('Cloud backup restored.');}}
 else if(a==='delete-account'){if(prompt('Type DELETE to permanently delete your EasyTime cloud data.')!=='DELETE')return;await api('state','DELETE',{confirm:'DELETE'});try{localStorage.removeItem('easytimeFreshDraft:'+user.id);localStorage.removeItem('easytimeActiveRecord');}catch{}dirty=false;clearInterval(refreshTimer);location.href='login.html?deleted=1';}
 else if(a==='signout')await signout();
 }catch(error){toast(error.message);}}
$('view').addEventListener('click',action);$('reminder-list').addEventListener('click',action);
$('view').addEventListener('change',async e=>{if(e.target.id!=='backup-file'||!e.target.files[0])return;try{const file=e.target.files[0];if(file.size>MAX_BACKUP_FILE_BYTES)throw new Error('Choose an EasyTime backup smaller than 32 MB.');const next=readAccountBackup(await file.text());if(!confirm('Replace your cloud workspace with this backup? A recovery version will be saved.'))return;state=next;selectRecord(state.records.at(-1)??newRecord(today(),state.settings.cycle,state.settings.rate));touch();if(await flush()){route();toast('Your records were restored from the backup.');}}catch(error){toast(error.message);}});
$('retry-save').addEventListener('click',async()=>{if(conflict){downloadAccountBackup();if(confirm('Your unsaved backup is downloaded. Reload the latest cloud records now?'))location.reload();}else if(!user)boot();else if(await flush()){if($('budget-dialog').open){showBudget();budgetFeedback('Budget limits saved for this pay cycle.');}}});
$('budget-dialog').addEventListener('pointerdown',beginBudgetDrag);$('budget-dialog').addEventListener('pointermove',moveBudgetDrag);$('budget-dialog').addEventListener('pointerup',e=>{if(budgetDrag?.pointerId===e.pointerId)finishBudgetDrag();});$('budget-dialog').addEventListener('pointercancel',()=>finishBudgetDrag(true));$('budget-dialog').addEventListener('lostpointercapture',()=>finishBudgetDrag(true));$('budget-dialog').addEventListener('keydown',e=>{const handle=e.target.closest('[data-budget-drag]');if(e.key==='Escape'&&budgetDrag){e.preventDefault();finishBudgetDrag(true);return;}if(!handle||!['ArrowUp','ArrowDown','Home','End'].includes(e.key))return;e.preventDefault();const row=handle.closest('[data-budget-row]'),rows=budgetRows(),at=rows.indexOf(row);moveBudgetRow(row,e.key==='Home'?0:e.key==='End'?rows.length-1:at+(e.key==='ArrowUp'?-1:1));});$('budget-dialog').addEventListener('click',e=>{const control=e.target.closest('[data-budget-move]');if(!control)return;const row=control.closest('[data-budget-row]');moveBudgetRow(row,budgetRows().indexOf(row)+(control.dataset.budgetMove==='up'?-1:1));});
for(const dialog of document.querySelectorAll('dialog')){let outsidePress=false;const outside=e=>{const r=dialog.getBoundingClientRect();return e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom;};dialog.addEventListener('pointerdown',e=>{outsidePress=e.target===dialog&&outside(e);});dialog.addEventListener('click',e=>{const dismiss=outsidePress&&e.target===dialog&&outside(e);outsidePress=false;if(dismiss&&!(dialog.id==='budget-dialog'&&(budgetBusy||budgetDrag))&&!(dialog.id==='delete-record-dialog'&&recordDeleteBusy))dialog.close();});}
$('confirm-delete-record').addEventListener('click',confirmRecordDelete);$('cancel-delete-record').addEventListener('click',()=>{if(!recordDeleteBusy)$('delete-record-dialog').close();});$('delete-record-dialog').addEventListener('cancel',e=>{if(recordDeleteBusy)e.preventDefault();});$('delete-record-dialog').addEventListener('close',()=>{pendingRecordDelete='';});
$('close-budget').addEventListener('click',()=>{if(!budgetBusy)$('budget-dialog').close();});$('budget-dialog').addEventListener('submit',saveBudget);$('budget-dialog').addEventListener('cancel',e=>{if(budgetBusy||budgetDrag){e.preventDefault();if(budgetDrag)finishBudgetDrag(true);}});$('budget-dialog').addEventListener('click',e=>{if(e.target.closest('a')&&!budgetBusy)$('budget-dialog').close();});
$('close-spending').addEventListener('click',()=>$('spending-dialog').close());$('spending-paycheck').addEventListener('change',e=>showSpending(e.target.value));$('spending-dialog').addEventListener('click',e=>{if(e.target.closest('a'))$('spending-dialog').close();});
$('close-balance').addEventListener('click',()=>$('balance-dialog').close());$('balance-dialog').addEventListener('click',e=>{if(e.target.closest('a'))$('balance-dialog').close();});
$('signout').addEventListener('click',()=>signout().catch(e=>toast(e.message)));$('reminder-button').addEventListener('click',()=>{$('reminder-list').innerHTML=reminderHTML();$('reminder-dialog').showModal();});$('close-reminders').addEventListener('click',()=>$('reminder-dialog').close());$('calendar-download').addEventListener('click',calendar);$('enable-notifications').addEventListener('click',async()=>{if(!('Notification' in window)){toast('This browser does not support notifications. Use calendar reminders.');return;}const permission=await Notification.requestPermission();if(permission==='granted'){try{for(const r of reminders().filter(r=>r.date===today()).slice(0,3))new Notification(r.title,{body:r.copy,tag:r.id});toast('Browser notifications enabled while EasyTime is open.');}catch{toast('Use calendar reminders on this device.');}}else toast('Notifications were not enabled. Calendar reminders are still available.');});
$('navigation').addEventListener('click',e=>{const link=e.target.closest('[data-view]');if(!link)return;e.preventDefault();history.pushState(null,'','#'+link.dataset.view);route();$('main').focus({preventScroll:true});window.scrollTo(0,0);});
window.addEventListener('popstate',route);window.addEventListener('hashchange',route);window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});window.addEventListener('online',()=>flush());
async function boot(){if(location.protocol==='file:'){$('view').innerHTML=head('Open your EasyTime website','Cloud accounts need the hosted website.')+`<section class="panel"><p>Use your private EasyTime link for cloud features, or open the original offline calculator.</p><div class="button-row" style="margin-top:20px"><a class="button" href="https://easytime-15-day.allup-pegasian.chatgpt.site" target="_blank" rel="noopener">Open private EasyTime</a><a class="button secondary" href="calculator.html">Offline calculator</a></div></section>`;syncText('Cloud saving needs the hosted version');return;}try{const result=await api('state');state=result.state;validateState(state);user=result.user;revision=result.revision;let activeId,mode='normal';try{activeId=localStorage.getItem('easytimeActiveRecord');mode=localStorage.getItem('easytimeMode')==='overtime'?'overtime':'normal';localImport=!!localStorage.getItem('easytimeRecordsV1')&&!state.records.length;}catch{}selectRecord(state.records.find(r=>r.id===activeId)??restoreFreshDraft(activeId)??state.records.slice().sort((a,b)=>b.start.localeCompare(a.start))[0]??newRecord(today(),state.settings.cycle,state.settings.rate||state.profile.rate||'20',mode));$('user-avatar').textContent=(state.profile.fullName||user.name).split(/\s+/).slice(0,2).map(n=>n[0]).join('').toUpperCase();syncText('Your private records are synced to cloud','saved');route();clearInterval(refreshTimer);refreshTimer=setInterval(async()=>{if(dirty||saving||document.querySelector('dialog[open]')||document.visibilityState!=='visible'||document.activeElement?.matches('input,select,textarea'))return;try{const r=await api('state');if(r.revision!==revision){const activeId=active.id;state=r.state;revision=r.revision;active=state.records.find(x=>x.id===activeId)??active;route();syncText('Synced changes from another device','saved');}refreshReminders();}catch{}},30000);
 }catch(error){if(error.status===401){location.href='login.html';return;}syncText(error.message,'error');$('view').innerHTML=head('Your records are safe.','The cloud connection could not be opened.')+`<section class="panel"><p>Reconnect and retry to open your workspace.</p><div class="button-row" style="margin-top:20px"><a class="button" href="login.html">Sign in</a><a class="button secondary" href="calculator.html">Open offline calculator</a></div></section>`;}}
boot();
